"use strict";(globalThis.webpackChunkmiko_docusaurus_en=globalThis.webpackChunkmiko_docusaurus_en||[]).push([[849],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/introduction","label":"Introduction","docId":"introduction","unlisted":false},{"type":"category","label":"The AI Agent Market","items":[{"type":"link","href":"/docs/ecosystem/the-ai-agent-era","label":"The AI Agent Era","docId":"ecosystem/the-ai-agent-era","unlisted":false},{"type":"link","href":"/docs/ecosystem/competitive-landscape","label":"Competitive Landscape","docId":"ecosystem/competitive-landscape","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"The MIKO Protocol","items":[{"type":"link","href":"/docs/miko-protocol/core-components","label":"Core Components","docId":"miko-protocol/core-components","unlisted":false},{"type":"link","href":"/docs/miko-protocol/symbiotic-loop-and-economics","label":"Symbiotic Loop & Economics","docId":"miko-protocol/symbiotic-loop-and-economics","unlisted":false},{"type":"link","href":"/docs/miko-protocol/what-miko-allocates-and-why","label":"What MIKO Allocates and Why","docId":"miko-protocol/what-miko-allocates-and-why","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Technical Architecture","items":[{"type":"link","href":"/docs/technical-architecture/ai-architecture","label":"AI Architecture","docId":"technical-architecture/ai-architecture","unlisted":false},{"type":"link","href":"/docs/technical-architecture/smart-contracts","label":"Smart Contracts","docId":"technical-architecture/smart-contracts","unlisted":false},{"type":"category","label":"Built with MIKO","items":[{"type":"link","href":"/docs/technical-architecture/built-with-miko/rest-api","label":"REST API","docId":"technical-architecture/built-with-miko/rest-api","unlisted":false},{"type":"link","href":"/docs/technical-architecture/built-with-miko/mcp-server","label":"MCP Server","docId":"technical-architecture/built-with-miko/mcp-server","unlisted":false},{"type":"link","href":"/docs/technical-architecture/built-with-miko/open-model","label":"Open Model","docId":"technical-architecture/built-with-miko/open-model","unlisted":false}],"collapsed":true,"collapsible":true}],"collapsed":true,"collapsible":true},{"type":"category","label":"Ecosystem & Vision","items":[{"type":"link","href":"/docs/ecosystem/tokenomics-and-distribution","label":"Tokenomics & Distribution","docId":"ecosystem/tokenomics-and-distribution","unlisted":false},{"type":"link","href":"/docs/ecosystem/roadmap","label":"Roadmap","docId":"ecosystem/roadmap","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Security & Risks","items":[{"type":"link","href":"/docs/security/risks-and-transparency","label":"Risks & Transparency","docId":"security/risks-and-transparency","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","href":"/docs/conclusion","label":"Conclusion","docId":"conclusion","unlisted":false}]},"docs":{"conclusion":{"id":"conclusion","title":"Conclusion","description":"The AI agent era is here. It is not hype. It is not a bubble. It is a genuine technological shift.","sidebar":"tutorialSidebar"},"ecosystem/competitive-landscape":{"id":"ecosystem/competitive-landscape","title":"Competitive Landscape","description":"The AI agent crypto market has grown into a multi-billion dollar vertical, spanning platforms, agent frameworks, and autonomous trading agents. MIKO Protocol occupies a distinct position within this landscape as an AI curation protocol whose selections \u2014 a weekly curated core and a continuously tracked attention satellite \u2014 are acquired on-chain and allocated pro-rata to eligible holders. This page covers MIKO\'s position among AI agent projects; for how MIKO compares with other allocation-economy models, see What MIKO Allocates and Why.","sidebar":"tutorialSidebar"},"ecosystem/roadmap":{"id":"ecosystem/roadmap","title":"Roadmap","description":"The MIKO Protocol will continuously grow and evolve through a clear, phased development plan. Each phase builds on the success of the previous one, with the AI model being continuously enhanced throughout all stages. The ultimate goal is to build the standard for AI-curated weekly asset selection and allocation to token holders.","sidebar":"tutorialSidebar"},"ecosystem/the-ai-agent-era":{"id":"ecosystem/the-ai-agent-era","title":"The AI Agent Era","description":"The convergence of AI and cryptocurrency is the defining trend of 2026. To understand MIKO Protocol\'s position, it is essential to understand where this trend came from, where it stands today, and what problem remains unsolved.","sidebar":"tutorialSidebar"},"ecosystem/tokenomics-and-distribution":{"id":"ecosystem/tokenomics-and-distribution","title":"Tokenomics & Distribution","description":"MIKO Protocol\u2019s tokenomics are designed with fairness, long-term sustainability, and community trust as the highest priorities. The model is straightforward, transparent, and built to mitigate risks associated with team token holdings.","sidebar":"tutorialSidebar"},"introduction":{"id":"introduction","title":"Introduction","description":"Welcome to the documentation of the MIKO Protocol, a token ecosystem native to Robinhood Chain where an AI agent\'s intelligence is structurally converted into on-chain asset selection, acquisition, and allocation for its token holders. Every week, the Miko AI Agent analyzes the Robinhood Chain ecosystem and selects the week\'s core asset \u2014 while a satellite sleeve continuously tracks the market\'s live attention leader \u2014 and its on-chain module autonomously acquires both and allocates them to all eligible \\\\$MIKO holders pro-rata.","sidebar":"tutorialSidebar"},"miko-protocol/core-components":{"id":"miko-protocol/core-components","title":"Core Components","description":"Overview","sidebar":"tutorialSidebar"},"miko-protocol/symbiotic-loop-and-economics":{"id":"miko-protocol/symbiotic-loop-and-economics","title":"Symbiotic Loop & Economics","description":"1. The Symbiotic Loop: A Self-Reinforcing Value Cycle","sidebar":"tutorialSidebar"},"miko-protocol/what-miko-allocates-and-why":{"id":"miko-protocol/what-miko-allocates-and-why","title":"What MIKO Allocates and Why","description":"Every tax-funded allocation protocol has to answer one question before any other: when the treasury fills up, what should it buy? The answer defines who the protocol is for, what its holders actually receive, and whether the model survives a market that never stops rotating. This page explains MIKO\'s answer, and how it differs from the models that came before it.","sidebar":"tutorialSidebar"},"security/risks-and-transparency":{"id":"security/risks-and-transparency","title":"Risks & Transparency","description":"As the MIKO Protocol combines autonomous systems with financial incentives, it prioritizes security and fairness, and has established multi-layered measures to protect users and maintain trust.","sidebar":"tutorialSidebar"},"technical-architecture/ai-architecture":{"id":"technical-architecture/ai-architecture","title":"AI Architecture","description":"Miko\'s intelligence is not a single model responding to prompts. It is a production system composed of specialized layers, each engineered for a specific function in the pipeline from raw data to on-chain execution. This section details each layer \u2014 what it does, how it works, and why it matters for holders.","sidebar":"tutorialSidebar"},"technical-architecture/built-with-miko/mcp-server":{"id":"technical-architecture/built-with-miko/mcp-server","title":"MCP Server","description":"MIKO is exposed as a Model Context Protocol server. Any MCP-aware client can call MIKO\'s capabilities as tools directly inside its own conversation context, so a holder can use MIKO from Claude Desktop, Cursor, OpenAI Agents, Gemini, or any other MCP-aware workflow.","sidebar":"tutorialSidebar"},"technical-architecture/built-with-miko/open-model":{"id":"technical-architecture/built-with-miko/open-model","title":"Open Model","description":"You\'ve met Miko on X. The open model brings her everywhere else too \u2014 her persona, packaged as open weights you can download and run. She isn\'t only someone you follow now; she\'s someone you can host. On your own machine, in your community, inside your apps \u2014 the same Miko, wherever you want her.","sidebar":"tutorialSidebar"},"technical-architecture/built-with-miko/rest-api":{"id":"technical-architecture/built-with-miko/rest-api","title":"REST API","description":"The MIKO REST API exposes MIKO\'s capabilities over standard HTTP. Every request is authenticated with a wallet-signed JWT, and every response is JSON.","sidebar":"tutorialSidebar"},"technical-architecture/smart-contracts":{"id":"technical-architecture/smart-contracts","title":"Smart Contracts","description":"Miko\'s intelligence stack produces analytical decisions off-chain. These decisions are executed on Robinhood Chain through a set of verified smart contracts and Miko\'s on-chain execution module. This hybrid architecture maximizes off-chain analytical flexibility while ensuring on-chain transparency: every deployed contract is verifiable against its published source code, so any change to on-chain logic is itself public.","sidebar":"tutorialSidebar"}}}}')}}]);